function buildAIPrompt(q){
  const modes={
    simple:"Explain in very simple English for a beginner. Use short sentences and practical examples.",
    deep:"Teach as an expert tutor. Give a complete, structured, deep explanation from basics to advanced understanding. Never give only a definition.",
    exam:"Create an MBA/exam-ready answer with introduction, definition, headings, key points, examples, formula/calculation if relevant, conclusion, and a short 5-mark version.",
    interview:"Teach the topic first, then provide a confident interview answer, likely follow-up questions and model answers.",
    english:"Act as an English speaking coach. Correct the user's English, explain each important error, provide natural alternatives, pronunciation help, vocabulary and practice.",
    finance:"Act as an MBA Finance tutor. Explain concepts with formulas, define variables, calculations, business examples, advantages, limitations and exam/interview answers."
  };
  return `You are the real AI tutor inside the Daily Learning website.
MODE: ${modes[S.aiMode]||modes.deep}

USER QUESTION:
${q}

IMPORTANT:
- Answer the user's exact question. Do not return a fixed canned answer.
- Do not stop after one definition or one example.
- Teach the user so they can understand and explain the topic themselves.
- For academic topics, use suitable sections: meaning, purpose, key concepts, types/components, how it works, step-by-step process, example, practical application, advantages, limitations, common mistakes, quick revision.
- For finance/accounting, include formulas and a small numerical example when useful; define every variable.
- For English, correct mistakes and explain why they are mistakes.
- For coding, provide complete working code when asked.
- For comparisons, use a table.
- If the user asks a short question, answer it directly but add useful context rather than padding.
- If current information is needed and search grounding is enabled, use it.
- Never pretend that you performed an action you did not perform.
- End longer teaching answers with “Quick revision” and 3 practice questions.`;
}

async function callGemini(q){
  if(!S.aiKey)throw new Error("Gemini is not connected. Open ⚙ Gemini settings and add your API key.");
  const model=S.aiModel||"gemini-3.7-flash";
  const previous=(S.aiHistory||[]).slice(-10).map(m=>({role:m.role==="model"?"model":"user",parts:[{text:m.text}]}));
  const contents=[...previous,{role:"user",parts:[{text:buildAIPrompt(q)}]}];
  const body={contents,generationConfig:{thinkingConfig:{thinkingLevel:S.aiMode==="simple"?"low":S.aiMode==="deep"?"high":"medium"},maxOutputTokens:16000}};
  if(S.aiSearch)body.tools=[{google_search:{}}];
  const url=`https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(model)}:generateContent`;
  const r=await fetch(url,{method:"POST",headers:{"Content-Type":"application/json","x-goog-api-key":S.aiKey},body:JSON.stringify(body)});
  const data=await r.json();
  if(!r.ok)throw new Error(data?.error?.message||"Gemini request failed.");
  const text=(data?.candidates?.[0]?.content?.parts||[]).map(p=>p.text||"").join("");
  if(!text)throw new Error("Gemini returned an empty answer.");
  return text;
}

async function askAI(){
  const i=document.getElementById("aiInput");if(!i)return;
  const q=i.value.trim();if(!q){toast("Type a question first.");return}
  addMsg(q,"user");S.aiHistory.push({role:"user",text:q});i.value="";
  const box=document.getElementById("messages");
  const typing=document.createElement("div");typing.className="ai-message from-ai";typing.id="aiTyping";
  typing.innerHTML='<div class="ai-msg-icon">✦</div><div class="ai-msg-body"><div class="ai-msg-name">Daily Learning AI</div><div class="ai-thinking"><span></span><span></span><span></span> Thinking deeply...</div></div>';
  box.appendChild(typing);box.scrollTop=box.scrollHeight;
  try{
    const answer=await callGemini(q);
    typing.remove();addMsg(answer,"bot");S.aiHistory.push({role:"model",text:answer});save();
  }catch(err){
    typing.remove();
    const fallback=`### Gemini is not answering yet\n\n${err.message}\n\nOpen **⚙ Gemini settings**, add a valid Gemini API key, save it, and ask your question again.\n\nOnce connected, this screen will generate a new answer for every question instead of using fixed demo sentences.`;
    addMsg(fallback,"bot");S.aiHistory.push({role:"model",text:fallback});save();
  }
}
